module.exports = {
    onConnect: function(transport, config) {
        engine.setStatus("connecting", "Initializing ZoomOSC Session...");
    },
    onTransportReady: function(transport, config) {
        engine.setStatus("connected", "ZoomOSC Session Active");
        var sub = engine.osc.encode("/zoom/subscribe", [1]);
        transport.sendBytes(sub);
    },
    onHeartbeat: function(transport) {
        var sub = engine.osc.encode("/zoom/subscribe", [1]);
        transport.sendBytes(sub);
    },
    onAction: function(transport, actionId, params) {
        if (actionId === "zoom_get_meeting_status" || actionId === "get_meeting_status" || actionId === "get_status") {
            var isMuted = engine.getVariable("zoom_all_muted") || "false";
            return "Zoom Meeting Muted: " + isMuted;
        }
        if (actionId === "zoom_mute_all" || actionId === "mute_all") {
            var packet = engine.osc.encode("/zoom/all/mute", []);
            transport.sendBytes(packet);
            engine.setVariable("zoom_mute_status", "muted");
            return "Muted All Participants";
        }
        if (actionId === "zoom_unmute_all" || actionId === "unmute_all") {
            var packet = engine.osc.encode("/zoom/all/unMute", []);
            transport.sendBytes(packet);
            engine.setVariable("zoom_mute_status", "unmuted");
            return "Unmuted All Participants";
        }
        if (actionId === "zoom_spotlight" || actionId === "spotlight") {
            var name = params.user_name || "Host";
            var packet = engine.osc.encode("/zoom/userName/spot", [name]);
            transport.sendBytes(packet);
            return "Spotlighted " + name;
        }
        return "Zoom Action Executed";
    },
    onMessage: function(transport, text, bytes) {
        var osc = engine.osc.decode(bytes);
        if (!osc || !osc.address) return;
        if (osc.address.indexOf("/zoom/user/") === 0) {
            engine.setVariable("zoom_active_speaker", String(osc.args[0] || ""));
        }
    }
};
